CREATE TABLE airport (id VARCHAR(36) PRIMARY KEY, code VARCHAR(3) NOT NULL UNIQUE);
CREATE TABLE airline (id VARCHAR(36) PRIMARY KEY, code VARCHAR(2) NOT NULL UNIQUE);
CREATE TABLE route (id VARCHAR(36) PRIMARY KEY, code VARCHAR(7) NOT NULL UNIQUE, origin_id VARCHAR(36) NOT NULL, destination_id VARCHAR(36) NOT NULL, UNIQUE(origin_id,destination_id), FOREIGN KEY(origin_id) REFERENCES airport(id), FOREIGN KEY(destination_id) REFERENCES airport(id), CHECK(origin_id<>destination_id));
CREATE TABLE data_source (id VARCHAR(36) PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, synthetic BIT NOT NULL, CHECK(synthetic=1));
CREATE TABLE dataset (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(36) NOT NULL UNIQUE, source_id VARCHAR(36) NOT NULL, model_version VARCHAR(40) NOT NULL, config_hash VARCHAR(64) NOT NULL, canonical_config LONGTEXT NOT NULL, synthetic BIT NOT NULL, CHECK(synthetic=1), FOREIGN KEY(source_id) REFERENCES data_source(id));
CREATE TABLE fare_product (id VARCHAR(36) PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, cabin VARCHAR(20) NOT NULL, adults INT NOT NULL, nonstop BIT NOT NULL, one_way BIT NOT NULL, CHECK(adults=1 AND cabin='ECONOMY' AND nonstop=1 AND one_way=1));
CREATE TABLE flight_service (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(36) NOT NULL UNIQUE, route_id VARCHAR(36) NOT NULL, airline_id VARCHAR(36) NOT NULL, flight_number VARCHAR(30) NOT NULL, local_time TIME(6) NOT NULL, FOREIGN KEY(route_id) REFERENCES route(id), FOREIGN KEY(airline_id) REFERENCES airline(id), UNIQUE(route_id,airline_id,flight_number,local_time));
CREATE TABLE flight_departure (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(36) NOT NULL UNIQUE, service_id VARCHAR(36) NOT NULL, departure_date DATE NOT NULL, departure_at DATETIME(6) NOT NULL, arrival_at DATETIME(6) NOT NULL, time_band VARCHAR(20) NOT NULL, FOREIGN KEY(service_id) REFERENCES flight_service(id), UNIQUE(service_id,departure_at), CHECK(arrival_at>departure_at), INDEX idx_departure_date(departure_date,service_id));
CREATE TABLE collection_run (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(36) NOT NULL, dataset_id VARCHAR(36) NOT NULL, collection_date DATE NOT NULL, observed_at DATETIME(6) NOT NULL, idempotency_key VARCHAR(100) NOT NULL, payload_hash VARCHAR(64) NOT NULL, result_count INT NOT NULL, FOREIGN KEY(dataset_id) REFERENCES dataset(id), UNIQUE(dataset_id,collection_date), UNIQUE(dataset_id,idempotency_key), UNIQUE(dataset_id,external_id), CHECK(result_count>0));
CREATE TABLE collection_result (id VARCHAR(36) PRIMARY KEY, external_id VARCHAR(36) NOT NULL, run_id VARCHAR(36) NOT NULL, departure_id VARCHAR(36) NOT NULL, product_id VARCHAR(36) NOT NULL, horizon INT NOT NULL, outcome VARCHAR(20) NOT NULL, FOREIGN KEY(run_id) REFERENCES collection_run(id), FOREIGN KEY(departure_id) REFERENCES flight_departure(id), FOREIGN KEY(product_id) REFERENCES fare_product(id), UNIQUE(run_id,departure_id,product_id), UNIQUE(run_id,external_id), CHECK(horizon BETWEEN 1 AND 45), CHECK(outcome IN ('AVAILABLE','SOLD_OUT','NO_OFFER','TIMEOUT','SOURCE_BLOCKED','PARSE_ERROR','RATE_LIMITED')), INDEX idx_result_departure(departure_id,horizon));
CREATE TABLE fare_observation (id VARCHAR(36) PRIMARY KEY, result_id VARCHAR(36) NOT NULL UNIQUE, total_amount DECIMAL(12,2), currency VARCHAR(3) NOT NULL, synthetic BIT NOT NULL, FOREIGN KEY(result_id) REFERENCES collection_result(id), CHECK(total_amount IS NULL OR total_amount>0), CHECK(currency='INR'), CHECK(synthetic=1));
CREATE TABLE simulation_inventory_state (id VARCHAR(36) PRIMARY KEY, result_id VARCHAR(36) NOT NULL UNIQUE, remaining INT NOT NULL, arrivals INT NOT NULL, cancellations INT NOT NULL, FOREIGN KEY(result_id) REFERENCES collection_result(id), CHECK(remaining>=0 AND arrivals>=0 AND cancellations>=0));
CREATE TABLE calendar_event (id VARCHAR(36) PRIMARY KEY, dataset_id VARCHAR(36) NOT NULL, route_id VARCHAR(36) NOT NULL, name VARCHAR(100) NOT NULL, event_date DATE NOT NULL, window_start DATE NOT NULL, window_end DATE NOT NULL, date_source VARCHAR(80) NOT NULL, FOREIGN KEY(dataset_id) REFERENCES dataset(id), FOREIGN KEY(route_id) REFERENCES route(id), UNIQUE(dataset_id,route_id,name,event_date), CHECK(window_start<=event_date AND window_end>=event_date));
CREATE TABLE price_alert (id VARCHAR(36) PRIMARY KEY, dataset_id VARCHAR(36) NOT NULL, route_id VARCHAR(36) NOT NULL, departure_date DATE NOT NULL, threshold DECIMAL(12,2) NOT NULL, active BIT NOT NULL, FOREIGN KEY(dataset_id) REFERENCES dataset(id), FOREIGN KEY(route_id) REFERENCES route(id), CHECK(threshold>0));
CREATE TABLE alert_notification (id VARCHAR(36) PRIMARY KEY, alert_id VARCHAR(36) NOT NULL, result_id VARCHAR(36) NOT NULL, amount DECIMAL(12,2) NOT NULL, observed_at DATETIME(6) NOT NULL, FOREIGN KEY(alert_id) REFERENCES price_alert(id), FOREIGN KEY(result_id) REFERENCES collection_result(id), UNIQUE(alert_id,result_id));
